import os, requests, xml.etree.ElementTree as ET
os.chdir('/home/data4/xiangyu/BioDSA/workdir')
for pmid in ['27501330','32757336']:
    u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi'
    r=requests.get(u,params={'db':'pubmed','id':pmid,'retmode':'xml'},timeout=20)
    root=ET.fromstring(r.text)
    print('\nPMID',pmid)
    for n in root.findall('.//ArticleTitle'): print('TITLE',''.join(n.itertext()))
    for n in root.findall('.//Abstract/AbstractText'):
        print(n.attrib.get('Label','ABSTRACT'),''.join(n.itertext()))
